contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint initVal, uint newVal) public payable {
        require(initVal != newVal);

        c.SetMinSum(initVal); if (__ESBMC_reverted()) return;
        uint minAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(newVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint minAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted && minAfterFirst == initVal && minAfterSecond == newVal);
    }

    receive() external payable {}
}

