pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 initVal, uint256 newVal) internal {
        vm.assume(initVal != newVal);
        try c.SetMinSum(initVal) {} catch { return; }
        uint256 minAfterFirst;
        try c.MinSum() returns (uint256 __r) { minAfterFirst = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(newVal) { reverted = false; } catch { reverted = true; }
        uint256 minAfterSecond;
        try c.MinSum() returns (uint256 __r) { minAfterSecond = __r; } catch { return; }
        assertTrue(!reverted && minAfterFirst == initVal && minAfterSecond == newVal);
    }

    function testFuzz_run(uint256 initVal, uint256 newVal) public {
        _run(initVal, newVal);
    }

    receive() external payable {}
}
